INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'estrategia', 'Estrategia', 'Turras sobre estrategia empresarial: qué es y qué no es estrategia, propuestas de valor que caducan, declive, reinvención y cómo esquivar la competencia.', 'Estrategia en el sentido de Richard Rumelt: diagnosticar el problema decisivo y actuar de forma coherente, no fijar objetivos ni hacer planes a cinco años. Aquí están las turras sobre propuestas de valor que caducan, empresas y sectores en declive, reinvención, sidestepping y lectura del tablero competitivo.', 'Entra: qué es (y qué no es) estrategia; propuesta de valor y su caducidad; declive y reinvención de empresas, clubes o sectores; posicionamiento y movimientos competitivos (sidestepping, océano azul, metajuego); pricing como decisión estratégica; anticipar cambios de juego. No entra: cómo se organiza la empresa por dentro, incentivos o cultura (→ Organizaciones e incentivos); finanzas, private equity o inversión (→ Finanzas e inversión); marketing o publicidad (→ Marketing y publicidad). Desempate: si trata de hacia dónde va la empresa en su mercado → Estrategia; si trata de por qué la gente dentro de la empresa se comporta como lo hace → Organizaciones e incentivos.', 0 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'metodo-cps', 'Método CPS', 'Qué es la resolución de problemas complejos (CPS) como disciplina: cómo se practica, en qué se diferencia de la consultoría, cómo se aprende y cómo se vende.', 'CPS (Complex Problem Solving) es la disciplina de la que parte todo este archivo. Esta categoría reúne solo las turras cuyo tema es la propia disciplina: qué es y qué no es, en qué se diferencia de la consultoría, cómo se forma a un CPSer, cómo se vende y qué iniciativas la llevan a la práctica.', 'Entra: definición y naturaleza del CPS (cienciarte, no skill ni framework); CPS frente a consultoría; cómo se vende y se contrata; formación y libros para CPSers; iniciativas y empresas que lo aplican (Singular Solving, ¡Ajá!, UnconventionalCPS, Solvers Academy); la organización de la comunidad CPS; el Factor X solo cuando la turra lo define o lo defiende como parte de la disciplina; la tesis del CPS Hispano frente a la cultura «luterana» de la medición y la optimización. No entra: turras que solo aplican el CPS a otro tema (van al tema); teoría de la complejidad o sensemaking (→ Sistemas complejos y sensemaking). Desempate: si la pregunta es «qué es y cómo se ejerce el CPS» → Método CPS; si es «cómo se comporta un sistema complejo» → Sistemas complejos y sensemaking.', 1 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'sistemas-complejos', 'Sistemas complejos y sensemaking', 'Turras sobre complejidad: por qué los sistemas complejos no se descomponen, el peso del contexto, la incertidumbre, las señales débiles y el sensemaking.', 'Un sistema complejo produce comportamientos que no se deducen de sus partes. Estas turras tratan la complejidad en sí: la diferencia entre complicado y complejo, el contexto que manda, la incertidumbre y la suerte, las señales débiles y el sensemaking de Karl Weick para darle sentido a lo que pasa.', 'Entra: complejidad frente a complicación o aleatoriedad; problemas irresolubles; el contexto como determinante (no hay soluciones context-free); incertidumbre, suerte y serendipia; lectura de señales débiles; sensemaking como marco o disciplina (Weick, aporía); procesos de alta variabilidad; casos presentados como ejemplo de problema complejo (ITER). No entra: la disciplina CPS como oficio (→ Método CPS); sesgos y psicología individual (→ Psicología y decisiones). Desempate: si explica cómo es la realidad compleja → aquí; si explica por qué las personas la perciben mal → Psicología y decisiones. La incertidumbre como propiedad del sistema (cisnes y elefantes negros) → aquí; cómo percibimos el riesgo → Psicología y decisiones.', 2 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'equipos-y-liderazgo', 'Equipos y liderazgo', 'Turras sobre equipos de talento y liderazgo: cómo se orquestan perfiles extremos, por qué fallan los equipos de estrellas y qué hace a un líder.', 'Los problemas complejos los resuelven equipos de talentos muy distintos, y eso exige orquestarlos: la «orquestación cognitiva». Aquí están las turras sobre equipos, talento y liderazgo, a menudo explicadas con deporte o música, pero siempre sobre cómo funciona un grupo de personas brillantes.', 'Entra: orquestación cognitiva; equipos de talento (síndrome de Apolo, emulsificadores, relato compartido); diversidad cognitiva; liderazgo y figura del líder; selección y encaje del talento; errores de casting. No entra: incentivos y cultura de toda la organización (→ Organizaciones e incentivos); desarrollo de una persona concreta (→ Desarrollo personal). Desempate: si el sujeto es el equipo o quien lo dirige → aquí; si es la empresa como sistema → Organizaciones e incentivos.', 3 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'organizaciones-e-incentivos', 'Organizaciones e incentivos', 'Turras sobre cómo funcionan las empresas por dentro: incentivos, cultura, problemas de agencia, grandes corporaciones, empresa familiar y resistencia al cambio.', 'La cultura de una empresa no se diseña: emerge de sus incentivos. Estas turras explican cómo funcionan las organizaciones por dentro, desde los problemas de agencia y el juego corporativo hasta la empresa familiar, la homeostasis y quienes bloquean el cambio.', 'Entra: arquitecturas de incentivos y problemas de agencia; cultura organizativa; juego corporativo y política interna; grandes corporaciones frente a startups; empresa familiar; homeostasis y resistencia interna al cambio; reparto de poder entre roles de la alta dirección; tecnología o metodologías de gestión (Agile, OKR, taylorismo) aplicadas a la organización. No entra: posicionamiento en el mercado (→ Estrategia); equipos concretos (→ Equipos y liderazgo); finanzas (→ Finanzas e inversión). Desempate: ver Estrategia y Equipos y liderazgo. Un rol concreto de la alta dirección va a la categoría de su función (CMO → Marketing y publicidad, CFO → Finanzas e inversión, CTO → IA y tecnología).', 4 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'finanzas-e-inversion', 'Finanzas e inversión', 'Turras sobre private equity, capital riesgo, M&A y el poder de los financieros en la empresa: sus ciclos, sus límites y por qué necesitan otra mirada.', 'Del apalancamiento de los 80 a la crisis de liquidez actual: estas turras analizan el private equity, el capital riesgo, las fusiones y adquisiciones y el ascenso de los financieros al poder corporativo, y por qué la ingeniería financiera ya no basta para crear valor.', 'Entra: private equity, venture capital, M&A, fondos distress; historia de los paradigmas financieros; el CFO y el presupuesto; financiación de startups; crisis de liquidez; capital frente a creación de valor. No entra: estrategia de una empresa aunque la compre un fondo, salvo que el tema sea el fondo (→ Estrategia). Desempate: si el protagonista es el dinero o quien lo gestiona → aquí. Si la turra propone una alternativa estratégica u operativa al private equity (CFU, post-PE) y el private equity es el sujeto, sigue siendo Finanzas e inversión.', 5 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'marketing', 'Marketing y publicidad', 'Turras sobre la crisis del marketing y la publicidad: Facebook y Google, fraude publicitario, agencias, atención, marca, patrocinio y ventas.', 'El marketing basado en comprar audiencia barata está agotado. Estas turras analizan la industria publicitaria, el fraude digital, el papel del CMO, la atención y la relevancia de marca, el patrocinio y la función comercial.', 'Entra: industria publicitaria y agencias; Facebook/Google Ads y adtech; fraude publicitario; el rol del CMO; iniciativas o empresas que atacan problemas de marketing (fraude publicitario, marcas lifestyle, Insight Lab); atención, marca y relevancia; patrocinio; ventas y generación de demanda; influencia y persuasión comercial. No entra: personalización a escala y el método de la personotecnia (→ Personotecnia). Desempate: si trata del sector o de sus prácticas → Marketing y publicidad; si trata de adaptar el mensaje o el producto a cada persona → Personotecnia.', 6 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'personotecnia', 'Personotecnia', 'Turras sobre personotecnia: personalizar a escala sin big data ni engaño, relevancia frente a atención y cómo tratar a cada cliente como persona.', 'La personotecnia es la disciplina de tratar a cada persona como individuo a escala, como hace la frutera de barrio, sin disfrazar de personalización el big data. Estas turras explican qué es, por qué la falsa personalización inmuniza a la gente y cómo se aplica a marcas, productos y ventas.', 'Entra: qué es la personotecnia; humanización y personalización a escala; romper el tradeoff escala/precisión; D2C y personalización de producto; personotecnia aplicada a ventas o a narrativas; economía de la atención leída desde la personotecnia. No entra: crítica a la industria publicitaria (→ Marketing y publicidad). Desempate: ver Marketing y publicidad. No entra: pricing (→ Estrategia).', 7 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'psicologia-y-decisiones', 'Psicología y decisiones', 'Turras sobre cómo decidimos: sesgos, emociones, autoengaño, por qué no cambiamos de opinión, el riesgo y el factor humano en los problemas.', 'Los problemas complejos los deciden personas, y las personas no son racionales. Estas turras tratan los sesgos, la emoción que secuestra decisiones, el autoengaño, la dificultad de cambiar de opinión y el Factor X: la parte humana que los modelos racionales ignoran.', 'Entra: sesgos cognitivos y heurísticos; percepción del riesgo; emoción en la toma de decisiones; autoengaño, mentira y truth coping; cambiar de opinión y querer tener razón; datos frente a intuición; el factor humano como causa de que fallen los planes (si analiza un mecanismo humano concreto; si define el concepto Factor X → Método CPS); por qué alguien no cambia su marco de sentido; percepción del riesgo. No entra: conducta de grupos o de la sociedad (→ Sociedad y política); crecimiento personal y carrera (→ Desarrollo personal). Desempate: mecanismo mental de un individuo → aquí; fenómeno colectivo → Sociedad y política; qué debería hacer una persona con su vida → Desarrollo personal. Desempate con Sociedad y política: si el mecanismo solo existe en la interacción social (espiral del silencio, groupthink, confianza, conformidad) → Sociedad y política, aunque se explique con experimentos individuales.', 8 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'desarrollo-personal', 'Desarrollo personal', 'Turras sobre crecer como profesional: asertividad, resiliencia, carrera, emprender, perseverar o abandonar, obsesión, fracaso y síndrome del impostor.', 'Consejos que no caben en un libro de autoayuda: estas turras tratan la asertividad, la resiliencia, la carrera profesional y la «shadow career», emprender, cuándo perseverar y cuándo abandonar, la obsesión, el fracaso como dato y el síndrome del impostor.', 'Entra: habilidades personales (asertividad, resiliencia, gestión del estrés); carrera profesional y empleabilidad individual; emprender como decisión vital; perseverar o abandonar; pasión, obsesión y equilibrio; fracaso y responsabilidad; síndrome del impostor; hábitos como la escritura. No entra: mecanismos psicológicos generales (→ Psicología y decisiones); relatos íntimos del autor (→ Reflexiones personales). Desempate: si da criterio para actuar en la propia vida profesional → aquí.', 9 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'sociologia', 'Sociedad y política', 'Turras sobre sociedad y política: polarización, pensamiento de grupo, opinión pública, relato frente a dato y una Administración incapaz de reformarse.', 'Cómo piensan y se comportan los grupos y las instituciones: polarización y pensamiento en blanco y negro, conformidad, espiral del silencio, confianza y engaño, el relato que vence al dato, y por qué la Administración y los partidos no saben gestionar la complejidad.', 'Entra: polarización, bothism y maniqueísmo; conformidad y groupthink; opinión pública y espiral del silencio; confianza y engaño social; relato frente a dato; privilegio, moral y valor como construcciones sociales; ideas controvertidas y cancelación; hipocresía social; pompismo e idealismo; Administración pública y burocracia; partidos, políticos e incentivos políticos; demografía y estrategia de país; reconversiones industriales y subvenciones; innovación y sector público; acción civil. No entra: sesgos individuales (→ Psicología y decisiones). Desempate: ver Psicología y decisiones.', 10 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'ia-y-tecnologia', 'IA y tecnología', 'Turras sobre inteligencia artificial y tecnología: la IA frente al trabajo intelectual, su adopción real en empresas, hype, Web3 y el papel del CTO.', 'La IA encapsulará todo trabajo intelectual que se pueda modelar de forma determinista. Estas turras analizan qué queda para las personas, cómo adoptan la IA las empresas de verdad, cómo distinguir una tendencia de un hype y qué papel tiene la tecnología en los problemas de negocio.', 'Entra: IA y su impacto en el trabajo y en el CPS; adopción de IA en empresas (IA chasm, centauros); tecnología subordinada a la estrategia; tendencias frente a hype; grandes fuerzas de cambio y atractores de futuro; Web3 y nuevos paradigmas; redes sociales como plataformas tecnológicas; killer apps. No entra: IA en la educación (→ Educación y altas capacidades); publicidad en plataformas (→ Marketing y publicidad). Desempate: si el tema es la tecnología en sí o su adopción → aquí.', 11 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'educacion-y-altas-capacidades', 'Educación y altas capacidades', 'Turras sobre educación, altas capacidades y neurodivergencia: el sistema educativo, la IA en el aula, el MBA, Mensa y la empleabilidad de las AACC.', 'El sistema educativo enseña a seguir el surco, no a gestionar la incertidumbre, y tritura a quien no encaja. Estas turras tratan la educación de la infancia a la tercera edad, las altas capacidades y la neurodivergencia, la IA en el aula y el futuro de universidades y escuelas de negocio.', 'Entra: sistema educativo y escuela; universidades, MBA y escuelas de negocio; IA en educación; altas capacidades y neurodivergencia (educación, socialización, empleabilidad, Mensa); formación a lo largo de la vida. No entra: programas formativos cuyo contenido es el CPS, como másteres o academias CPS (→ Método CPS). Desempate: si el sujeto son alumnos, escuelas o personas con altas capacidades → aquí.', 12 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'cultura-popular', 'Cómic, cine y videojuegos', 'Turras sobre cultura popular como tema: la industria del videojuego, el cómic, la música, el cine y la creación artística, y lo que enseñan de talento y éxito.', 'Cómics, videojuegos, música y cine aparecen en casi todas las turras como ejemplo. Aquí están las que los tratan como tema: la industria del videojuego y su monetización, cómo se forman los cánones culturales, el talento que no triunfa y cómo un artista construye su público.', 'Entra: la industria cultural (videojuegos, cómic, música, cine) y sus modelos de negocio; creación artística y talento artístico; mitos y cánones culturales; reseñas de obras cuando la tesis final trata de la obra, su autor o su industria. No entra: turras que usan una obra como metáfora de otro tema (van al tema). Desempate: si quitando la obra la turra sigue en pie, la obra es vehículo y la categoría es otra.', 13 WHERE EXISTS (SELECT 1 FROM threads);
INSERT INTO categories (slug, name, description, intro, criteria, position) SELECT 'reflexiones-personales', 'Reflexiones personales', 'Turras personales de Javier G. Recuenco: duelos, elegías, la muerte, cierres de etapa, la historia de las turras y la comunidad que las lee.', 'No todo es empresa y complejidad. Estas son las turras más personales: elegías por su madre y por amigos, reflexiones sobre la muerte, cierres de etapa, la historia de las propias turras y el agradecimiento a la comunidad que se ha formado alrededor.', 'Entra: elegías y duelos; la muerte; cierres de etapas vitales; la historia de las turras; homenajes, celebraciones y agradecimientos a la comunidad; aficiones personales del autor contadas en primera persona. No entra: consejos de carrera o habilidades (→ Desarrollo personal). Desempate: si el centro es la vida del autor y no una tesis → aquí.', 14 WHERE EXISTS (SELECT 1 FROM threads);
